Следующая программа на C++ читает текстовый файл построчно и подсчитывает количество вхождений определенного слова в файл:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    std::string word; // Слово, которое будем искать
    std::cout << "Enter the word to search for: ";
    std::cin >> word;

    std::string file_name; // Имя файла
    std::cout << "Enter the file name: ";
    std::cin >> file_name;

    std::ifstream file(file_name); // Открытие файла в режиме чтения
    if (!file.is_open()) { // Проверка на успешную открытие файла
        std::cerr << "Error opening file!" << std::endl;
        return 1;
    }

    std::string line; // Строка из файла
    int count = 0; // Счетчик вхождений слова

    while (std::getline(file, line)) { // Чтение файла построчно
        std::transform(line.begin(), line.end(), line.begin(), ::tolower); // Приведение строки к нижнему регистру
        size_t pos = std::string::npos; // Инициализация позиции для std::string::find

        while ((pos = line.find(word, pos)) != std::string::npos) { // Поиск слова в строке
            count++; // Увеличение счетчика вхождений
            pos++; // Увеличение позиции для следующего поиска
        }
    }

    std::cout << "The word '" << word << "' appears " << count << " times in " << file_name << "." << std::endl;

    file.close(); // Закрытие файла

    return 0;
}
```

